import os
import sys
import shutil
import tkinter as tk
from tkinter import filedialog, messagebox, simpledialog
import customtkinter as ctk
from PIL import Image
from datetime import datetime
import json
import base64
from io import BytesIO

# ---------------------- UI Configuration ----------------------
ctk.set_appearance_mode("Dark")
ctk.set_default_color_theme("blue")

# ---------------------- Built-in Default Logo (Base64) ----------------------
# ⚠️ IMPORTANT: Replace this string with your own logo's Base64 value ⚠️
DEFAULT_LOGO_BASE64 = """

"""
# ------------------------------------------------------------------

class R6SettingsApp(ctk.CTk):
    def __init__(self):
        super().__init__()

        self.title("R6 Profile Sync & Server Fixer By BinSaleh")
        self.geometry("700x800")
        self.resizable(False, False)

        # Load settings (custom names, saved path)
        self.settings_file = "r6_tool_settings.json"
        self.load_settings()
        
        # Detect or ask for game path
        self.r6_path = self.detect_or_ask_path()
        
        # Profile data
        self.profiles_map = {}  # maps display text -> folder ID
        self.raw_dirs = []

        # ---------------------- Server List for Dropdown ----------------------
        self.server_options = {
            "🌍 Default (Auto Select)": "default",
            "-----------------------------------": None,
            "🇺🇸 North America": None,
            "   • East US": "playfab/eastus",
            "   • Central US": "playfab/centralus",
            "   • South Central US": "playfab/southcentralus",
            "   • West US": "playfab/westus",
            "-----------------------------------": None,
            "🇧🇷 South America": None,
            "   • Brazil South": "playfab/brazilsouth",
            "-----------------------------------": None,
            "🇪🇺 Europe": None,
            "   • North Europe": "playfab/northeurope",
            "   • West Europe": "playfab/westeurope",
            "-----------------------------------": None,
            "🇿🇦 Africa": None,
            "   • South Africa North": "playfab/southafricanorth",
            "-----------------------------------": None,
            "🌏 Asia": None,
            "   • East Asia": "playfab/eastasia",
            "   • Southeast Asia": "playfab/southeastasia",
            "   • Japan West": "playfab/japanwest",
            "-----------------------------------": None,
            "🇦🇺 Oceania": None,
            "   • Australia East": "playfab/australiaeast",
            "   • Australia Southeast": "playfab/australiasoutheast",
        }
        # ----------------------------------------------------------------

        self.setup_ui()
        self.load_profiles()

    def load_settings(self):
        """Load custom names and saved R6 path from JSON file."""
        if os.path.exists(self.settings_file):
            try:
                with open(self.settings_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    self.custom_names = data.get("custom_names", {})
                    self.saved_path = data.get("r6_path", None)
            except:
                self.custom_names = {}
                self.saved_path = None
        else:
            self.custom_names = {}
            self.saved_path = None

    def save_settings(self):
        """Save custom names and current R6 path to JSON file."""
        data = {
            "r6_path": self.r6_path,
            "custom_names": self.custom_names
        }
        try:
            with open(self.settings_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=4)
        except:
            pass

    def detect_r6_path(self):
        """Search for Rainbow Six Siege profile folder in all possible locations."""
        user_home = os.path.expanduser('~')
        # Get all available drives (C:\, D:\, etc.)
        drives = [f"{d}:\\" for d in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" if os.path.exists(f"{d}:\\")]

        possible_paths = [
            # Standard Documents
            os.path.join(user_home, 'Documents', 'My Games', 'Rainbow Six - Siege'),
            # OneDrive Documents
            os.path.join(user_home, 'OneDrive', 'Documents', 'My Games', 'Rainbow Six - Siege'),
            # Saved Games (sometimes used by Steam)
            os.path.join(user_home, 'Saved Games', 'Rainbow Six - Siege'),
            # Alternative if user moved Documents folder
            os.path.join(os.environ.get('USERPROFILE', ''), 'Documents', 'My Games', 'Rainbow Six - Siege'),
            # Direct under My Games
            os.path.join(user_home, 'My Games', 'Rainbow Six - Siege'),
        ]

        # Add paths on other drives
        for drive in drives:
            possible_paths.append(os.path.join(drive, 'Users', os.path.basename(user_home), 'Documents', 'My Games', 'Rainbow Six - Siege'))
            possible_paths.append(os.path.join(drive, 'Users', os.path.basename(user_home), 'OneDrive', 'Documents', 'My Games', 'Rainbow Six - Siege'))
            possible_paths.append(os.path.join(drive, 'Users', os.path.basename(user_home), 'Saved Games', 'Rainbow Six - Siege'))

        for path in possible_paths:
            if os.path.exists(path):
                # Verify that the folder contains profile directories
                try:
                    dirs = [d for d in os.listdir(path) if os.path.isdir(os.path.join(path, d)) and len(d) > 20]
                    if dirs:
                        return path
                except:
                    pass
        return None

    def ask_user_for_path(self):
        """Open a dialog for the user to manually select the R6 profile folder."""
        path = filedialog.askdirectory(title="Select the 'Rainbow Six - Siege' folder (contains long ID-named folders)")
        if path and os.path.exists(path):
            return path
        return None

    def detect_or_ask_path(self):
        """Use saved path if valid, else auto-detect, else ask user."""
        # Check saved path first
        if self.saved_path and os.path.exists(self.saved_path):
            try:
                dirs = [d for d in os.listdir(self.saved_path) if os.path.isdir(os.path.join(self.saved_path, d)) and len(d) > 20]
                if dirs:
                    return self.saved_path
            except:
                pass
        
        # Auto-detect
        detected = self.detect_r6_path()
        if detected:
            return detected
        
        # Ask user
        answer = messagebox.askyesno("Game Not Found", "Could not automatically find Rainbow Six Siege folder. Do you want to select it manually?")
        if answer:
            manual = self.ask_user_for_path()
            if manual:
                return manual
        
        messagebox.showerror("Error", "Cannot run without the game path. The program will exit.")
        sys.exit(1)

    def setup_ui(self):
        """Create all GUI elements."""
        # ----- Logo -----
        self.load_and_display_logo()
        
        # ----- Title -----
        self.title_label = ctk.CTkLabel(self, text="R6 Profile Manager & Server Fixer | By @BinSaleh", font=ctk.CTkFont(size=18, weight="bold"))
        self.title_label.pack(pady=5)

        # ----- Current path display -----
        path_text = f"📂 Game Path: {self.r6_path}" if self.r6_path else "⚠️ Path not found"
        self.path_label = ctk.CTkLabel(self, text=path_text, font=ctk.CTkFont(size=10), text_color="gray", wraplength=600)
        self.path_label.pack(pady=(5, 10))

        # ----- Profile selection frame -----
        self.src_frame = ctk.CTkFrame(self)
        self.src_frame.pack(pady=10, fill="x", padx=60)

        self.src_label = ctk.CTkLabel(self.src_frame, text="Select Main Profile (Source):", font=ctk.CTkFont(size=13, weight="bold"))
        self.src_label.pack(pady=5, padx=15, anchor="w")

        self.src_combo = ctk.CTkComboBox(self.src_frame, values=["Loading..."], width=480)
        self.src_combo.pack(pady=5)

        self.btn_rename = ctk.CTkButton(self.src_frame, text="✏️ Rename Selected Account", 
                                        command=self.rename_account,
                                        fg_color="#3a3a3a", hover_color="#505050", width=200, height=30)
        self.btn_rename.pack(pady=10)

        # ----- Action buttons -----
        self.btn_sync = ctk.CTkButton(self, text="Sync Settings to All Accounts", 
                                      command=self.sync_settings,
                                      fg_color="#1f538d", hover_color="#14375e",
                                      height=45, font=ctk.CTkFont(size=14, weight="bold"))
        self.btn_sync.pack(pady=10, fill="x", padx=60)

        # ----- Server selection frame -----
        self.server_frame = ctk.CTkFrame(self)
        self.server_frame.pack(pady=10, fill="x", padx=60)

        self.server_label = ctk.CTkLabel(self.server_frame, text="Select Game Server:", font=ctk.CTkFont(size=13, weight="bold"))
        self.server_label.pack(pady=5, padx=15, anchor="w")

        self.server_var = tk.StringVar()
        self.server_combo = ctk.CTkOptionMenu(self.server_frame, variable=self.server_var, values=list(self.server_options.keys()), width=480)
        self.server_combo.pack(pady=5)

        self.btn_apply_server = ctk.CTkButton(self.server_frame, text="✈️ Apply Selected Server (Change Region)",
                                              command=self.apply_server_setting,
                                              fg_color="#2e7d32", hover_color="#1b5e20",
                                              height=35, width=200)
        self.btn_apply_server.pack(pady=10)

        # ----- Manual path change button -----
        self.btn_change_path = ctk.CTkButton(self, text="📁 Change Game Path (if not working)", 
                                             command=self.change_game_path,
                                             fg_color="#555555", hover_color="#333333",
                                             height=35, font=ctk.CTkFont(size=12))
        self.btn_change_path.pack(pady=5, fill="x", padx=60)

        # ----- Footer -----
        self.footer = ctk.CTkLabel(self, text="v2.1 | Supports all R6 paths | @BinSaleh", 
                                   font=ctk.CTkFont(size=11), text_color="gray")
        self.footer.pack(side="bottom", pady=15)

    def load_and_display_logo(self):
        """Load logo from external logo.png or use built-in default Base64 image."""
        logo_image = None
        # Try external file
        if os.path.exists("logo.png"):
            try:
                logo_image = Image.open("logo.png")
            except:
                pass
        # Fallback to built-in
        if logo_image is None:
            try:
                img_data = base64.b64decode(DEFAULT_LOGO_BASE64.strip())
                logo_image = Image.open(BytesIO(img_data))
            except:
                pass
        if logo_image:
            # Resize for consistency
            logo_image = logo_image.resize((120, 120), Image.Resampling.LANCZOS)
            self.logo_ctk = ctk.CTkImage(light_image=logo_image, dark_image=logo_image, size=(120, 120))
            self.logo_label = ctk.CTkLabel(self, image=self.logo_ctk, text="")
            self.logo_label.pack(pady=(20, 0))
        else:
            # If no image at all, show an emoji
            self.logo_label = ctk.CTkLabel(self, text="🎮", font=ctk.CTkFont(size=60))
            self.logo_label.pack(pady=(20, 0))

    def change_game_path(self):
        """Manually change the R6 game path."""
        new_path = filedialog.askdirectory(title="Select the 'Rainbow Six - Siege' folder (contains long ID-named folders)")
        if new_path and os.path.exists(new_path):
            # Verify it contains profiles
            try:
                dirs = [d for d in os.listdir(new_path) if os.path.isdir(os.path.join(new_path, d)) and len(d) > 20]
                if dirs:
                    self.r6_path = new_path
                    self.save_settings()
                    self.path_label.configure(text=f"📂 Game Path: {self.r6_path}")
                    self.load_profiles()
                    messagebox.showinfo("Success", "Game path changed and profiles reloaded successfully.")
                else:
                    messagebox.showerror("Error", "This folder does not contain R6 profile folders (long ID names). Please select the correct folder.")
            except Exception as e:
                messagebox.showerror("Error", f"Cannot read folder: {e}")

    def load_profiles(self):
        """Load all profile folders from the game path and populate the dropdown."""
        if not self.r6_path or not os.path.exists(self.r6_path):
            self.src_combo.configure(values=["No path found"])
            self.src_combo.set("No path found")
            return

        try:
            # Get all subfolders with long names (typical R6 profile IDs)
            self.raw_dirs = [d for d in os.listdir(self.r6_path) if os.path.isdir(os.path.join(self.r6_path, d)) and len(d) > 20]
            self.profiles_map.clear()
            display_list = []

            for d in self.raw_dirs:
                path = os.path.join(self.r6_path, d)
                mtime = os.path.getmtime(path)
                dt_str = datetime.fromtimestamp(mtime).strftime('%Y-%m-%d %H:%M')
                alias = self.custom_names.get(d, f"Account_{d[:6]}")
                label = f"👤 {alias} | (ID: {d[:6]}...) | Last active: {dt_str}"
                self.profiles_map[label] = d
                display_list.append(label)

            if display_list:
                # Sort by last active (most recent first)
                display_list.sort(key=lambda x: x.split("Last active: ")[1], reverse=True)
                self.src_combo.configure(values=display_list)
                self.src_combo.set(display_list[0])
            else:
                self.src_combo.configure(values=["No profiles found"])
                self.src_combo.set("No profiles found")
        except Exception as e:
            messagebox.showerror("Error", f"Failed to load profiles: {e}")

    def rename_account(self):
        """Rename the currently selected profile (custom name)."""
        selected_label = self.src_combo.get()
        src_id = self.profiles_map.get(selected_label)
        if not src_id:
            messagebox.showwarning("Warning", "Please select a valid profile.")
            return
        current_alias = self.custom_names.get(src_id, f"Account_{src_id[:6]}")
        new_name = simpledialog.askstring("Rename Account", f"Enter a nickname for account (ID: {src_id[:6]}...):", 
                                          initialvalue=current_alias)
        if new_name and new_name.strip():
            self.custom_names[src_id] = new_name.strip()
            self.save_settings()
            self.load_profiles()
            messagebox.showinfo("Success", "Account renamed successfully!")

    def sync_settings(self):
        """Copy GameSettings.ini from source profile to all other profiles."""
        selected_label = self.src_combo.get()
        src_id = self.profiles_map.get(selected_label)
        if not src_id:
            messagebox.showwarning("Warning", "Please select a valid source profile.")
            return
        src_file = os.path.join(self.r6_path, src_id, 'GameSettings.ini')
        if not os.path.exists(src_file):
            messagebox.showerror("Error", "Source GameSettings.ini file not found!")
            return
        try:
            count = 0
            for label, profile_id in self.profiles_map.items():
                if profile_id == src_id:
                    continue
                dest_file = os.path.join(self.r6_path, profile_id, 'GameSettings.ini')
                shutil.copy(src_file, dest_file)
                count += 1
            messagebox.showinfo("Success", f"Settings synced to {count} account(s) successfully!")
        except Exception as e:
            messagebox.showerror("Error", f"Sync failed: {e}")

    def apply_server_setting(self):
        """Apply the selected server setting to all profiles."""
        selected_name = self.server_var.get()
        server_value = self.server_options.get(selected_name)
        
        if not server_value:
            messagebox.showwarning("Warning", "Please select a valid server.")
            return
        
        try:
            count = 0
            for profile_id in self.profiles_map.values():
                file_path = os.path.join(self.r6_path, profile_id, 'GameSettings.ini')
                if os.path.exists(file_path):
                    with open(file_path, 'r', encoding='utf-8') as f:
                        lines = f.readlines()
                    
                    found = False
                    for i, line in enumerate(lines):
                        if line.strip().startswith("DataCenterHint="):
                            lines[i] = f"DataCenterHint={server_value}\n"
                            found = True
                            break
                    
                    if not found:
                        lines.append(f"DataCenterHint={server_value}\n")
                    
                    with open(file_path, 'w', encoding='utf-8') as f:
                        f.writelines(lines)
                    count += 1
            
            messagebox.showinfo("Success", f"Game server changed to '{selected_name}' for {count} account(s)!")
        except Exception as e:
            messagebox.showerror("Error", f"Failed to modify server: {e}")

if __name__ == "__main__":
    app = R6SettingsApp()
    app.mainloop()